import os,json,shutil,pathlib,subprocess,re
root=pathlib.Path('/home/appontrack/public_html')
private=pathlib.Path('/home/appontrack/.ontrack-saas')
safe=lambda s: ('[sensitive]' if re.search(r'key|token|secret|password|config|credentials|auth|^\.env',s,re.I) else s)
def scan(path):
 try:
  if not path.exists():return {'exists':False}
  vals=[]
  for ent in sorted(path.iterdir()):
   st=ent.lstat()
   vals.append({'name':safe(ent.name),'type':'symlink' if ent.is_symlink() else ('dir' if ent.is_dir() else 'file'),'bytes':st.st_size if ent.is_file() else None})
  return {'exists':True,'is_symlink':path.is_symlink(),'entries':vals[:65],'total_entries':len(vals)}
 except Exception as exc:return {'error':type(exc).__name__}
fs=shutil.disk_usage('/home/appontrack')
webroot=pathlib.Path('/home/appontrack/public_html')
paths={'root':scan(webroot),'saas':scan(webroot/'saas'),'console':scan(webroot/'saas/console'),'mobile':scan(webroot/'saas/mobile'),'api':scan(webroot/'api'),'private':scan(private)}
ht={}
for path in ['.htaccess','saas/.htaccess','saas/console/.htaccess']:
 p=webroot/path
 if p.is_file():
  s=p.read_text(errors='replace')
  ht[path]={'bytes':len(s),'contains_rewrite':('RewriteRule' in s),'contains_console_path':('/saas/console' in s),'contains_mobile_path':('/saas/mobile' in s)}
print(json.dumps({'paths':paths,'htaccess':ht,'free_disk_gb':round(fs.free/1024**3,2),'used_disk_gb':round(fs.used/1024**3,2),'php83':pathlib.Path('/opt/cpanel/ea-php83/root/usr/bin/php').is_file(),'expected_root':str(webroot)},ensure_ascii=False))
